// These curves come from evaluated MCP Icon layer properties, not approximated easing.
const rightFrames=mcpReference.slide.map(([time,x,y])=>({
  offset:time*1000/mcpReference.duration,transform:`translate(${x}px, ${y}px)`
}));
const leftTrimFrames=mcpReference.outline.map(([time,end,angle])=>({
  offset:time*1000/mcpReference.duration,
  strokeDasharray:`${1-end/100} ${end/100}`,
  strokeDashoffset:`${-(end/100+angle/360)}`
}));
function animateMCP(trigger,svg) {
  const right=svg.querySelector('#mcp-right-stroke');
  const leftPaths=[...svg.querySelectorAll('[data-left-trim]')];
  return bindIconHover(trigger,svg,run=>{
    // AE keeps the left layer stationary and trims it; the front/right layer slides.
    run(right,rightFrames,{duration:mcpReference.duration,easing:'linear'});
    leftPaths.forEach(path=>run(path,leftTrimFrames,{duration:mcpReference.duration,easing:'linear'}));
  });
}

export default animateMCP;
